// FR3: constant-time comparison against TELEGRAM_WEBHOOK_SECRET, echoed back
// by Telegram in the X-Telegram-Bot-Api-Secret-Token header on every webhook
// call once setWebhook was called with secret_token (docs/setup/assistant-
// bot-setup.md). Same crypto.createHash('sha256') + crypto.timingSafeEqual
// pattern as gmail-renewal-recovery.json's 'Verify resync secret' -- secret
// read via $env, never an n8n credential, for the same reason draft-
// generation.json's 'Verify secret' documents (a Code node can't read an
// n8n credential's stored value directly).
try {
  const crypto = require('crypto');
  const item = $json || {};
  const headers = item.headers || {};
  const providedSecret = headers['x-telegram-bot-api-secret-token'] || '';
  const expectedSecret = $env.TELEGRAM_WEBHOOK_SECRET || '';

  const providedHash = crypto.createHash('sha256').update(String(providedSecret)).digest();
  const expectedHash = crypto.createHash('sha256').update(String(expectedSecret)).digest();

  const isValid = Boolean(expectedSecret) && Boolean(providedSecret) &&
    crypto.timingSafeEqual(providedHash, expectedHash);

  return { json: { authFailed: !isValid, update: item.body || item } };
} catch (err) {
  return { json: { authFailed: true, update: null, error: (err && err.message) || 'Unknown auth error' } };
}

// FR4: TELEGRAM_ALLOWED_CHAT_IDS is a comma-separated env var, compared as
// strings (Telegram chat ids are numeric but arrive as JSON numbers/strings
// depending on client -- String() on both sides avoids a type mismatch).
const update = $json.update || {};
const message = update.message || {};
const chatId = message.chat && message.chat.id !== undefined ? String(message.chat.id) : '';

const allowed = ($env.TELEGRAM_ALLOWED_CHAT_IDS || '')
  .split(',')
  .map((id) => id.trim())
  .filter((id) => id.length > 0);

const isAllowed = Boolean(chatId) && allowed.includes(chatId);

return { json: { chat_id: chatId, allowed: isAllowed, message } };

// Normalizes to the neutral { chat_id, text, channel } shape design.md's
// Architecture section specifies -- a future whatsapp-adapter.json would
// produce the exact same shape from a completely different source payload.
const message = $json.message || {};
const chatId = $json.chat_id;
const isText = typeof message.text === 'string' && message.text.length > 0;

return {
  json: {
    chat_id: chatId,
    text: isText ? message.text : null,
    channel: 'telegram',
    isText,
  },
};
